import type { BillingPageSummaryProps } from "@/components/mockups/billing-page-summary"
import { BillingPageSummary } from "@/components/mockups/billing-page-summary"
import type {
  InvoiceRecord,
  InvoiceTableLabels,
  InvoiceTableProps,
} from "@/components/mockups/invoice-table"
import { InvoiceTable } from "@/components/mockups/invoice-table"
import { buttonVariants } from "@/components/ui/button"
import { cn } from "@/lib/utils"

export type BillingWorkspaceEditorialContent = {
  heading: string
  description: string
  ctas: readonly {
    label: string
    href: string
  }[]
}

export type BillingWorkspaceProps = {
  content: BillingWorkspaceEditorialContent
  period: BillingPageSummaryProps["period"]
  paymentMethod: BillingPageSummaryProps["paymentMethod"]
  invoices: readonly InvoiceRecord[]
  invoiceLabels: InvoiceTableLabels
  managePaymentLabel: string
  managePaymentHref?: string
  onManagePayment?: BillingPageSummaryProps["onManagePayment"]
  getInvoiceDownloadHref?: InvoiceTableProps["getDownloadHref"]
  onDownloadInvoice?: InvoiceTableProps["onDownloadInvoice"]
}

export function BillingWorkspace({
  content,
  period,
  paymentMethod,
  invoices,
  invoiceLabels,
  managePaymentLabel,
  managePaymentHref,
  onManagePayment,
  getInvoiceDownloadHref,
  onDownloadInvoice,
}: BillingWorkspaceProps) {
  return (
    <div className="flex flex-col gap-8">
      <div className="flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between">
        <div className="max-w-2xl">
          <h1 className="text-2xl font-semibold text-balance">
            {content.heading}
          </h1>
          <p className="mt-2 text-sm text-balance text-muted-foreground">
            {content.description}
          </p>
        </div>
        {content.ctas.length ? (
          <div className="flex flex-wrap gap-2">
            {content.ctas.map((cta) => (
              <a
                key={`${cta.label}-${cta.href}`}
                className={cn(buttonVariants({ variant: "outline" }))}
                href={cta.href}
              >
                {cta.label}
              </a>
            ))}
          </div>
        ) : null}
      </div>
      <BillingPageSummary
        period={period}
        paymentMethod={paymentMethod}
        managePaymentLabel={managePaymentLabel}
        managePaymentHref={managePaymentHref}
        onManagePayment={onManagePayment}
      />
      <InvoiceTable
        invoices={invoices}
        labels={invoiceLabels}
        getDownloadHref={getInvoiceDownloadHref}
        onDownloadInvoice={onDownloadInvoice}
      />
    </div>
  )
}

"use client"

import { Button, buttonVariants } from "@/components/ui/button"
import {
  Card,
  CardAction,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import { cn } from "@/lib/utils"

export type BillingPeriodSummary = {
  label: string
  amount: string
  description: string
}

export type BillingPaymentMethod = {
  label: string
  name: string
  description: string
}

export type BillingPageSummaryProps = {
  period: BillingPeriodSummary
  paymentMethod: BillingPaymentMethod
  managePaymentLabel: string
  managePaymentHref?: string
  onManagePayment?: () => void
}

export function BillingPageSummary({
  period,
  paymentMethod,
  managePaymentLabel,
  managePaymentHref,
  onManagePayment,
}: BillingPageSummaryProps) {
  const managePaymentAction = managePaymentHref ? (
    <a
      className={cn(buttonVariants({ variant: "outline", size: "sm" }))}
      href={managePaymentHref}
    >
      {managePaymentLabel}
    </a>
  ) : (
    <Button
      variant="outline"
      size="sm"
      disabled={!onManagePayment}
      onClick={onManagePayment}
    >
      {managePaymentLabel}
    </Button>
  )

  return (
    <div className="grid gap-4 sm:grid-cols-2">
      <Card className="gap-2 rounded-sm">
        <CardHeader>
          <CardDescription>{period.label}</CardDescription>
          <CardTitle className="text-2xl font-medium tabular-nums">
            {period.amount}
          </CardTitle>
        </CardHeader>
        <CardContent>
          <p className="text-xs text-muted-foreground">{period.description}</p>
        </CardContent>
      </Card>
      <Card className="gap-2 rounded-sm">
        <CardHeader>
          <CardDescription>{paymentMethod.label}</CardDescription>
          <CardTitle className="text-2xl font-medium">
            {paymentMethod.name}
          </CardTitle>
          <CardAction>{managePaymentAction}</CardAction>
        </CardHeader>
        <CardContent>
          <p className="text-xs text-muted-foreground">
            {paymentMethod.description}
          </p>
        </CardContent>
      </Card>
    </div>
  )
}

"use client"

import { Badge } from "@/components/ui/badge"
import { Button, buttonVariants } from "@/components/ui/button"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import { cn } from "@/lib/utils"

export type InvoiceRecord = {
  id: string
  period: string
  amount: string
  status: string
  downloadHref?: string
}

export type InvoiceTableLabels = {
  title: string
  invoice: string
  period: string
  amount: string
  status: string
  download: string
  emptyTitle: string
  emptyDescription: string
}

export type InvoiceTableProps = {
  invoices: readonly InvoiceRecord[]
  labels: InvoiceTableLabels
  getDownloadHref?: (invoice: InvoiceRecord) => string | undefined
  onDownloadInvoice?: (invoice: InvoiceRecord) => void
}

export function InvoiceTable({
  invoices,
  labels,
  getDownloadHref,
  onDownloadInvoice,
}: InvoiceTableProps) {
  return (
    <div className="flex flex-col gap-3">
      <h2 className="text-sm font-medium">{labels.title}</h2>
      {invoices.length ? (
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>{labels.invoice}</TableHead>
              <TableHead>{labels.period}</TableHead>
              <TableHead className="text-right">{labels.amount}</TableHead>
              <TableHead>{labels.status}</TableHead>
              <TableHead className="text-right" />
            </TableRow>
          </TableHeader>
          <TableBody>
            {invoices.map((invoice) => {
              const downloadHref =
                getDownloadHref?.(invoice) ?? invoice.downloadHref
              const downloadAction = downloadHref ? (
                <a
                  className={cn(
                    buttonVariants({ variant: "ghost", size: "xs" })
                  )}
                  href={downloadHref}
                >
                  {labels.download}
                </a>
              ) : (
                <Button
                  variant="ghost"
                  size="xs"
                  disabled={!onDownloadInvoice}
                  onClick={() => onDownloadInvoice?.(invoice)}
                >
                  {labels.download}
                </Button>
              )

              return (
                <TableRow key={invoice.id}>
                  <TableCell className="font-mono text-xs">
                    {invoice.id}
                  </TableCell>
                  <TableCell>{invoice.period}</TableCell>
                  <TableCell className="text-right text-xs tabular-nums">
                    {invoice.amount}
                  </TableCell>
                  <TableCell>
                    <Badge variant="secondary">{invoice.status}</Badge>
                  </TableCell>
                  <TableCell className="text-right">{downloadAction}</TableCell>
                </TableRow>
              )
            })}
          </TableBody>
        </Table>
      ) : (
        <div className="flex min-h-40 flex-col items-center justify-center border-y px-4 text-center">
          <p className="text-sm font-medium">{labels.emptyTitle}</p>
          <p className="mt-1 max-w-sm text-sm text-muted-foreground">
            {labels.emptyDescription}
          </p>
        </div>
      )}
    </div>
  )
}
